import React, { useState, useCallback, useEffect } from "react";
import ReactFlow, {
  Background,
  Controls,
  MiniMap,
  addEdge,
  useNodesState,
  useEdgesState,
  MarkerType,
} from "reactflow";
import "reactflow/dist/style.css";
import {
  Box,
  Paper,
  Typography,
  Button,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Grid,
  Chip,
  Alert,
} from "@mui/material";
import {
  Add as AddIcon,
  Delete as DeleteIcon,
} from "@mui/icons-material";

// Node Types
const ConditionNode = ({ data, selected }) => {
  return (
    <Paper
      elevation={selected ? 8 : 2}
      sx={{
        p: 2,
        minWidth: 200,
        bgcolor: "#e3f2fd",
        border: selected ? "2px solid #1976d2" : "1px solid #bbb",
      }}
    >
      <Typography variant="subtitle2" fontWeight="bold" mb={1}>
        <Chip label="CONDITION" size="small" color="info" />
      </Typography>

      <Box sx={{ mt: 1 }}>
        <Typography variant="caption" color="text.secondary">
          Field: {data.field || "Not set"}
        </Typography>
        <Typography variant="caption" color="text.secondary" display="block">
          Operator: {data.operator || "Not set"}
        </Typography>
        <Typography variant="caption" color="text.secondary" display="block">
          Value: {data.value || "Not set"}
        </Typography>
      </Box>
    </Paper>
  );
};

const ActionNode = ({ data, selected }) => {
  return (
    <Paper
      elevation={selected ? 8 : 2}
      sx={{
        p: 2,
        minWidth: 250,
        bgcolor: "#f3e5f5",
        border: selected ? "2px solid #9c27b0" : "1px solid #bbb",
      }}
    >
      <Typography variant="subtitle2" fontWeight="bold" mb={1}>
        <Chip label="ACTION" size="small" color="secondary" />
      </Typography>

      <Box sx={{ mt: 1 }}>
        <Typography variant="caption" color="text.secondary">
          Code: {data.violationCode || "Not set"}
        </Typography>
        <Typography variant="caption" color="text.secondary" display="block">
          Weight: {data.weight || "Not set"} pts
        </Typography>
        <Typography 
          variant="caption" 
          color="text.secondary" 
          display="block"
          sx={{ 
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
            overflow: "hidden",
          }}
        >
          Message: {data.message || "Not set"}
        </Typography>
      </Box>
    </Paper>
  );
};

const StartNode = ({ data, selected }) => {
  return (
    <Paper
      elevation={selected ? 8 : 2}
      sx={{
        p: 2,
        minWidth: 150,
        bgcolor: "#e8f5e9",
        border: selected ? "2px solid #4caf50" : "1px solid #bbb",
      }}
    >
      <Chip label="START" size="small" color="success" />
    </Paper>
  );
};

const nodeTypes = {
  condition: ConditionNode,
  action: ActionNode,
  start: StartNode,
};

// Available fields based on data type
const AVAILABLE_FIELDS = {
  TRANSACTION: ["amount", "accountBalance", "paymentMethod", "type"],
  KYC: ["verifiedStatus", "documentType"],
  LOAN: ["amount", "interestRate", "termMonths", "applicantIncome", "creditScore"],
  CREDIT: ["score", "historyLength", "utilizationRate", "latePayments"],
  REPAYMENT: ["isLate", "daysPastDue", "amount", "currentBalance"],
};

const OPERATORS = [
  { value: ">", label: "Greater Than (>)" },
  { value: "<", label: "Less Than (<)" },
  { value: "==", label: "Equals (==)" },
  { value: "!=", label: "Not Equals (!=)" },
  { value: ">=", label: "Greater or Equal (>=)" },
  { value: "<=", label: "Less or Equal (<=)" },
];

const VisualRuleBuilder = ({ dataType, onDRLGenerated, initialDRL }) => {
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [selectedNode, setSelectedNode] = useState(null);
  const [showConditionForm, setShowConditionForm] = useState(false);
  const [showActionForm, setShowActionForm] = useState(false);
  const [conditionData, setConditionData] = useState({
    field: "",
    operator: ">",
    value: "",
  });
  const [actionData, setActionData] = useState({
    violationCode: "",
    weight: 10,
    message: "",
  });

  // Generate DRL from visual representation
  const generateDRL = useCallback(() => {
    if (nodes.length === 0) return "";

    // Find start node
    const startNode = nodes.find((n) => n.type === "start");
    const conditionNodes = nodes.filter((n) => n.type === "condition");
    const actionNodes = nodes.filter((n) => n.type === "action");

    if (conditionNodes.length === 0 || actionNodes.length === 0) {
      return "";
    }

    // Build when clauses
    const whenClauses = conditionNodes
      .map((node) => {
        const field = node.data.field;
        const operator = node.data.operator;
        const value = node.data.value;
        const valueType = node.data.valueType || "double";

        let fieldAccessor = "";
        switch (valueType) {
          case "boolean":
            fieldAccessor = `getBooleanProperty("${field}")`;
            break;
          case "int":
            fieldAccessor = `getIntProperty("${field}")`;
            break;
          case "string":
            fieldAccessor = `getStringProperty("${field}")`;
            break;
          default:
            fieldAccessor = `getDoubleProperty("${field}")`;
        }

        return `${fieldAccessor} ${operator} ${value}`;
      })
      .join("\n        ");

    // Build then clauses
    const thenClauses = actionNodes
      .map((node) => {
        return `$f.addViolation("${node.data.violationCode}", ${node.data.weight}, "${node.data.message}");`;
      })
      .join("\n    ");

    const ruleName = `Dynamic ${dataType} Rule`;
    const dataTypeLower = dataType.toLowerCase();

    const drl = `package rules;

import com.frauddetection.domain.DynamicFact;

rule "${ruleName}"
when
    $f: DynamicFact(
        dataType == "${dataTypeLower}",
        ${whenClauses}
    )
then
    ${thenClauses}
end`;

    return drl;
  }, [nodes, dataType]);

  // Trigger DRL generation when nodes change
  useEffect(() => {
    const drl = generateDRL();
    if (drl && onDRLGenerated) {
      onDRLGenerated(drl);
    }
  }, [nodes, generateDRL, onDRLGenerated]);

  const onConnect = useCallback(
    (params) => {
      setEdges((eds) =>
        addEdge(
          {
            ...params,
            type: "smoothstep",
            animated: true,
            style: { stroke: "#9c27b0", strokeWidth: 2 },
          },
          eds
        )
      );
    },
    [setEdges]
  );

  const addCondition = () => {
    const newNode = {
      id: `condition-${Date.now()}`,
      type: "condition",
      position: {
        x: Math.random() * 400,
        y: 150 + Math.random() * 200,
      },
      data: {
        field: conditionData.field,
        operator: conditionData.operator,
        value: conditionData.value,
        valueType: conditionData.valueType || "double",
      },
    };
    setNodes((nds) => [...nds, newNode]);
    setShowConditionForm(false);
    setConditionData({ field: "", operator: ">", value: "" });
  };

  const addAction = () => {
    const newNode = {
      id: `action-${Date.now()}`,
      type: "action",
      position: {
        x: Math.random() * 400 + 300,
        y: 400 + Math.random() * 200,
      },
      data: {
        violationCode: actionData.violationCode,
        weight: actionData.weight,
        message: actionData.message,
      },
    };
    setNodes((nds) => [...nds, newNode]);
    setShowActionForm(false);
    setActionData({ violationCode: "", weight: 10, message: "" });
  };

  const addStart = () => {
    const startNode = {
      id: "start",
      type: "start",
      position: { x: 200, y: 50 },
      data: {},
    };
    setNodes((nds) => [startNode, ...nds.filter((n) => n.id !== "start")]);
  };

  const deleteNode = (nodeId) => {
    setNodes((nds) => nds.filter((n) => n.id !== nodeId));
    setEdges((eds) => eds.filter((e) => e.source !== nodeId && e.target !== nodeId));
  };

  const updateNode = (nodeId, newData) => {
    setNodes((nds) =>
      nds.map((node) =>
        node.id === nodeId ? { ...node, data: { ...node.data, ...newData } } : node
      )
    );
  };

  const onNodeClick = (event, node) => {
    setSelectedNode(node);
    if (node.type === "condition") {
      setConditionData({
        field: node.data.field || "",
        operator: node.data.operator || ">",
        value: node.data.value || "",
        valueType: node.data.valueType || "double",
      });
      setShowConditionForm(true);
      setShowActionForm(false);
    } else if (node.type === "action") {
      setActionData({
        violationCode: node.data.violationCode || "",
        weight: node.data.weight || 10,
        message: node.data.message || "",
      });
      setShowActionForm(true);
      setShowConditionForm(false);
    }
  };

  const handleConditionSave = () => {
    if (selectedNode) {
      updateNode(selectedNode.id, conditionData);
      setShowConditionForm(false);
      setSelectedNode(null);
    } else {
      addCondition();
    }
  };

  const handleActionSave = () => {
    if (selectedNode) {
      updateNode(selectedNode.id, actionData);
      setShowActionForm(false);
      setSelectedNode(null);
    } else {
      addAction();
    }
  };

  return (
    <Box sx={{ height: "600px", position: "relative" }}>
      {/* Toolbar */}
      <Box
        sx={{
          mb: 2,
          p: 2,
          bgcolor: "#f5f5f5",
          borderRadius: 1,
          display: "flex",
          gap: 1,
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <Typography variant="body2" color="text.secondary">
          <strong>Visual Rule Builder</strong> - Drag nodes to position, click to edit
        </Typography>
        <Box sx={{ flexGrow: 1 }} />
        <Button
          size="small"
          variant="outlined"
          startIcon={<AddIcon />}
          onClick={addStart}
        >
          Add Start
        </Button>
        <Button
          size="small"
          variant="outlined"
          startIcon={<AddIcon />}
          onClick={() => {
            setShowConditionForm(true);
            setShowActionForm(false);
            setSelectedNode(null);
            setConditionData({ field: "", operator: ">", value: "" });
          }}
        >
          Add Condition
        </Button>
        <Button
          size="small"
          variant="outlined"
          startIcon={<AddIcon />}
          onClick={() => {
            setShowActionForm(true);
            setShowConditionForm(false);
            setSelectedNode(null);
            setActionData({ violationCode: "", weight: 10, message: "" });
          }}
        >
          Add Action
        </Button>
        {selectedNode && (
          <Button
            size="small"
            variant="outlined"
            color="error"
            startIcon={<DeleteIcon />}
            onClick={() => {
              deleteNode(selectedNode.id);
              setSelectedNode(null);
            }}
          >
            Delete Selected
          </Button>
        )}
      </Box>

      {/* Forms */}
      {showConditionForm && (
        <Paper
          sx={{
            p: 2,
            mb: 2,
            bgcolor: "#e3f2fd",
            border: "1px solid #1976d2",
          }}
        >
          <Typography variant="subtitle2" fontWeight="bold" mb={2}>
            {selectedNode ? "Edit Condition" : "Add New Condition"}
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth size="small">
                <InputLabel>Field</InputLabel>
                <Select
                  value={conditionData.field}
                  onChange={(e) =>
                    setConditionData({ ...conditionData, field: e.target.value })
                  }
                  label="Field"
                >
                  {AVAILABLE_FIELDS[dataType]?.map((field) => (
                    <MenuItem key={field} value={field}>
                      {field}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth size="small">
                <InputLabel>Operator</InputLabel>
                <Select
                  value={conditionData.operator}
                  onChange={(e) =>
                    setConditionData({ ...conditionData, operator: e.target.value })
                  }
                  label="Operator"
                >
                  {OPERATORS.map((op) => (
                    <MenuItem key={op.value} value={op.value}>
                      {op.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={3}>
              <TextField
                fullWidth
                size="small"
                label="Value"
                value={conditionData.value}
                onChange={(e) =>
                  setConditionData({ ...conditionData, value: e.target.value })
                }
                placeholder="10000"
              />
            </Grid>
            <Grid item xs={12} md={1}>
              <Button
                fullWidth
                variant="contained"
                onClick={handleConditionSave}
                size="small"
              >
                Save
              </Button>
            </Grid>
          </Grid>
        </Paper>
      )}

      {showActionForm && (
        <Paper
          sx={{
            p: 2,
            mb: 2,
            bgcolor: "#f3e5f5",
            border: "1px solid #9c27b0",
          }}
        >
          <Typography variant="subtitle2" fontWeight="bold" mb={2}>
            {selectedNode ? "Edit Action" : "Add New Action"}
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                size="small"
                label="Violation Code"
                value={actionData.violationCode}
                onChange={(e) =>
                  setActionData({ ...actionData, violationCode: e.target.value })
                }
                placeholder="RULE_001"
              />
            </Grid>
            <Grid item xs={12} md={2}>
              <TextField
                fullWidth
                size="small"
                type="number"
                label="Weight (points)"
                value={actionData.weight}
                onChange={(e) =>
                  setActionData({ ...actionData, weight: Number(e.target.value) })
                }
                inputProps={{ min: 0, max: 100 }}
              />
            </Grid>
            <Grid item xs={12} md={5}>
              <TextField
                fullWidth
                size="small"
                label="Message"
                value={actionData.message}
                onChange={(e) =>
                  setActionData({ ...actionData, message: e.target.value })
                }
                placeholder="Violation description"
              />
            </Grid>
            <Grid item xs={12} md={1}>
              <Button
                fullWidth
                variant="contained"
                onClick={handleActionSave}
                size="small"
                color="secondary"
              >
                Save
              </Button>
            </Grid>
          </Grid>
        </Paper>
      )}

      {/* React Flow */}
      <Box sx={{ height: "450px", border: "1px solid #ddd", borderRadius: 1 }}>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onNodeClick={onNodeClick}
          nodeTypes={nodeTypes}
          connectionLineType="smoothstep"
          defaultViewport={{ x: 0, y: 0, zoom: 0.8 }}
        >
          <Background color="#f0f0f0" />
          <Controls />
          <MiniMap nodeColor="#9c27b0" />
        </ReactFlow>
      </Box>

      {/* Info */}
      <Alert severity="info" sx={{ mt: 2 }}>
        <Typography variant="body2">
          <strong>How to use:</strong> Click "Add Start", then "Add Condition" to define
          rules. Connect nodes by dragging from the bottom of a node to the top of another.
          Click any node to edit it. The DRL code is generated automatically below.
        </Typography>
      </Alert>
    </Box>
  );
};

export default VisualRuleBuilder;
